import React, { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash/object'
import { size } from 'lodash/collection'
import { LayoutWrapper } from './index.style'
import {
  Card,
  Button,
  Table,
  Tag,
  Spin
} from 'antd'
import policyActions from '../../../../redux/policy/actions'
import { createCSV } from '../../../../helpers/utility'
import moment from 'moment-timezone'

const { getInsuranceOperationList, getDownloadOperationList, resetReduxState } = policyActions

class PolicyBulkRetryDetail extends Component {
  constructor (props) {
    super(props)
    this.state = {
      current: 1,
      operation_file_id: 0,
      fileData: {},
      pagination: {},
      count: 0,
      offset: 0,
      limit: 0,
      policyRetryFilerowData: [],
      isLoading: true
    }
  }

  componentWillReceiveProps (nextProps) {
    const {
      insuranceOperationListData,
      insuranceOperationListMessage,
      downloadOperationListMessage,
      downloadOperationListData,
    } = nextProps
    if (insuranceOperationListMessage === 'success') {
      this.setState({
        isLoading:false,
        policyRetryFilerowData: insuranceOperationListData.data.details,
        count:insuranceOperationListData.data.metadata.count
      })
      this.props.resetReduxState(['insuranceOperationListMessage','insuranceOperationListData'])
    }
    if (downloadOperationListMessage === 'success'){
      const fileUrl = downloadOperationListData.file_url
      this.downloadDataFromUrl(fileUrl)
    }
    this.props.resetReduxState(['downloadOperationListMessage','downloadOperationListData'])
  }
  componentWillMount () {
    const { history } = this.props
    const data = get(history, 'location.state', {})
    if (size(data) < 1) {
      history.push('/policy/bulk-policy-retry-list')
    }
  }

  downloadDataFromUrl = url => {
    const link = document.createElement('a')
    link.href = url
    link.setAttribute('download', 'insurance_operation_list.csv')
    document.body.appendChild(link)
    link.click()
  }

  componentDidMount () {
    const { history } = this.props
    const data = get(history, 'location.state', {})
    if ('file_url' in data) {
      this.props.getInsuranceOperationList({
        query:{
          operation_file_id : data.id,
          limit : 10,
          offset : 0
        }
      })
    }

    this.setState({
      fileData: { ...data },
      operation_file_id: data.id
    })
  }

  fetch = (params={}) => {
    const { offset, limit } = params
    const offsetNumber = Number(offset) || 0
    const limitNumber = Number(limit) || 10
    delete params.offset
    delete limit.offset
    this.props.getInsuranceOperationList({
      query:{
        ...params,
        limit: limitNumber,
        offset: offsetNumber,
      }
    })
  }

  csvContent = (item, arrayData = []) => {
    arrayData.push(item['file_row_no'])
    arrayData.push((item['file_status'] === 'True' ? 'SUCCESS' : 'FAILED'))
    arrayData.push(item['file_response'])
    arrayData.push(item['internal_id'])
    return arrayData
  }
  creatCSV =(val) => {
    switch (val) {
      case 'file-download-success': {
        const { policyRetryFilerowData, fileData } = this.state
        const data = []
        policyRetryFilerowData.filter(item => item['file_status'] === 'True').forEach(item => {
          data.push(this.csvContent(item))
        })
        const rowName = 'RowNo,Status,Error,InternalId'
        createCSV(data, get(fileData, 'file_name', ''), rowName)
      }
        break
      case 'file-download-failed': {
        const { policyRetryFilerowData, fileData } = this.state
        const data = []
        policyRetryFilerowData.filter(item => item['file_status'] === 'False').forEach(item => {
          data.push(this.csvContent(item))
        })
        const rowName = 'RowNo,Status,Error,InternalId'
        createCSV(data, get(fileData, 'file_name', ''), rowName)
      }
        break
      default: return null
    }
  }
  backButton = () => {
    this.props.history.push('/policy/bulk-policy-retry-list')
  }
  handleTableChange = pagination => {
    const { operation_file_id } = this.state
    const { pageSize, current } = pagination
      const offset = pageSize * (current - 1)
      this.setState({
        pagination,
        offset,
        limit: pageSize
      }, () => {
        this.fetch({
          operation_file_id,
          offset,
          limit: pageSize
        })
      })
      this.props.resetReduxState(['insuranceOperationListMessage','insuranceOperationListData'])
  }
  handleDownloadData = (status) => {
    const { operation_file_id } = this.state
    this.props.getDownloadOperationList({
      query:{
        operation_file_id,
        status
      }
    })
    // this.props.resetReduxState(['downloadOperationListMessage'])

  }
  render () {
    const { policyRetryFilerowData, count, fileData } = this.state
    const fileUrl = get(fileData, 'file_url', '')
    const tableColumns = [
      {
        title: 'Row No',
        key: 'file_row_no',
        dataIndex: 'file_row_no'
      },
      {
        title: 'Status',
        key: 'status',
        dataIndex: 'status',
      },
      {
        title: 'Error',
        key: 'message',
        dataIndex: 'message',
        render: (value, record) => {
          if (record.file_status === 'False' && !record.file_response) return <p>Policy not Retriable</p>
          else return value
        }
      },
      {
        title: 'Internal id',
        key: 'internal_id',
        dataIndex: 'internal_id',
      },
      {
        title: 'Present',
        key: 'is_present',
        dataIndex: 'is_present',
        render : (value) => (value)? 'True' : 'False'
      },
     

    ]
    return (
      <LayoutWrapper>
        <div className='top-section'>
          <Button onClick={this.backButton}>
            Back
          </Button>
          <Button type='primary' href={fileUrl} >
              Download File
          </Button>
        </div>
        <Card className='file-detail'>
          <div>
            <h3> File Detail </h3>
            <div>
              <div>
                <p>File name : {get(fileData, 'file_name', '')}</p>
                <p>Uploaded At : {moment(get(fileData, 'created_at', '')).format('MMMM Do YYYY hh:mm:ss')}</p>
                <p>Uploaded By : {get(fileData, 'user', '')}</p>
                <p>Status : {get(fileData, 'file_url', <Tag color='red'>FAILED</Tag>) && <Tag color='cyan'>SUCCESS</Tag>}</p>
              </div>
            </div>
          </div>
        </Card>
        <Card className='file-row-detail'>
          <div className='file-row-detail-body'>
            <h3>File Row Detail</h3>
            <div>
              <Button className='success-button' type='primary' onClick={() => this.handleDownloadData('SUCCESS')} > Download Success </Button>
              <Button className='failed-button' type='danger' onClick={() => this.handleDownloadData('FAILED')} > Download Failed </Button>
            </div>
          </div>
          <Spin spinning={!!this.state.isLoading}>
            <Table
              bordered
              columns={tableColumns}
              dataSource={policyRetryFilerowData}
              pagination={{
                total: count,
                pageSize: 10,
                current: this.state.offset / this.state.limit + 1
              }}
              onChange={this.handleTableChange}
            />
          </Spin>
        </Card>
      </LayoutWrapper>
    )
  }
}

export default connect(
  state => ({
    tableRowDataLoading: state.Policy.BULK_POLICY_RETRY_LIST_FILE_DATA,
    tableRowDataError: state.Error.BULK_POLICY_RETRY_LIST_FILE_DATA,
    tableRowData: state.Policy.policyRetryFileDetailData,
    tableRowDataMessage: state.Policy.policyRetryFileDetailDataMessage,
    insuranceOperationListData: state.Policy.insuranceOperationListData,
    insuranceOperationListMessage : state.Policy.insuranceOperationListMessage,
    downloadOperationListData: state.Policy.downloadOperationListData,
    downloadOperationListMessage: state.Policy.downloadOperationListMessage
  }), {
    resetReduxState,
    // bulkRetryFileDetail,
    getInsuranceOperationList,
    getDownloadOperationList
  }
)(PolicyBulkRetryDetail)
